"Hit":[{"s":"The ball hit the window.","he":"הכדור פגע בחלון.","l":2},{"s":"Prices hit a new record this year.","he":"המחירים הגיעו לשיא חדש השנה.","l":3}],
"Hurt":[{"s":"My back hurts.","he":"כואב לי הגב.","l":1},{"s":"I didn't want to hurt your feelings.","he":"לא רציתי לפגוע ברגשות שלך.","l":2}],
"Lend":[{"s":"Can you lend me a pen?","he":"אתה יכול להשאיל לי עט?","l":1},{"s":"The bank lent us money for the apartment.","he":"הבנק הלווה לנו כסף לדירה.","l":2}],
"Lead":[{"s":"She leads a team of ten people.","he":"היא מובילה צוות של עשרה אנשים.","l":2},{"s":"This road leads to the Old City.","he":"הדרך הזאת מובילה לעיר העתיקה.","l":2}],
"Mean":[{"s":"What does this word mean?","he":"מה פירוש המילה הזאת?","l":1},{"s":"Sorry, I meant Tuesday, not Thursday.","he":"סליחה, התכוונתי ליום שלישי, לא לחמישי.","l":2}],
"Ride":[{"s":"My kids ride their bikes in the park.","he":"הילדים שלי רוכבים על האופניים בפארק.","l":1},{"s":"I ride my bike to work every morning.","he":"אני רוכב לעבודה על האופניים כל בוקר.","l":2}],
"Shake":[{"s":"Shake the bottle before you open it.","he":"תנער את הבקבוק לפני שאתה פותח אותו.","l":2},{"s":"We shook hands and signed the deal.","he":"לחצנו ידיים וחתמנו על העסקה.","l":3}],
"Sing":[{"s":"We sing together on Friday night.","he":"אנחנו שרים ביחד ביום שישי בערב.","l":1},{"s":"She sings in the shower every day.","he":"היא שרה במקלחת כל יום.","l":1}],
"Steal":[{"s":"Someone stole my bike.","he":"מישהו גנב לי את האופניים.","l":2},{"s":"The thief tried to steal a laptop from the store, but the guard caught him.","he":"הגנב ניסה לגנוב מחשב נייד מהחנות, אבל המאבטח תפס אותו.","l":3}],
"Swim":[{"s":"I swim twice a week.","he":"אני שוחה פעמיים בשבוע.","l":1},{"s":"Can you swim in the sea?","he":"אתה יודע לשחות בים?","l":1}],
"Throw":[{"s":"Throw me the keys.","he":"תזרוק לי את המפתחות.","l":1},{"s":"She threw the ball to her brother.","he":"היא זרקה את הכדור לאח שלה.","l":2}],
"Cut":[{"s":"Cut the bread, please.","he":"תחתוך את הלחם, בבקשה.","l":1},{"s":"We need to cut costs this year.","he":"אנחנו צריכים לקצץ בעלויות השנה.","l":3}],
"Feed":[{"s":"Can you feed the baby?","he":"אתה יכול להאכיל את התינוק?","l":1},{"s":"We feed the cat twice a day.","he":"אנחנו מאכילים את החתול פעמיים ביום.","l":2}],
"Fight":[{"s":"The kids always fight over the remote.","he":"הילדים תמיד רבים על השלט.","l":2},{"s":"My brother and I used to fight a lot when we were kids.","he":"אחי ואני רבנו הרבה כשהיינו ילדים.","l":3}],
"Hang":[{"s":"Hang your coat here.","he":"תתלה את המעיל שלך כאן.","l":2},{"s":"Please hang the pictures on the wall before the guests arrive.","he":"בבקשה תתלה את התמונות על הקיר לפני שהאורחים מגיעים.","l":3}],
