"Quit":[{"s":"I quit smoking ten years ago.","he":"הפסקתי לעשן לפני עשר שנים.","l":2},{"s":"He quit his job to start a company.","he":"הוא התפטר מהעבודה שלו כדי להקים חברה.","l":2}],
"Prove":[{"s":"Can you prove it?","he":"אתה יכול להוכיח את זה?","l":2},{"s":"The numbers proved that we were right.","he":"המספרים הוכיחו שצדקנו.","l":3}],
"Lie":[{"s":"Don't lie to me.","he":"אל תשקר לי.","l":1},{"s":"He lied about his age.","he":"הוא שיקר לגבי הגיל שלו.","l":2}],
"Dream":[{"s":"I always dreamed of having my own company.","he":"תמיד חלמתי שתהיה לי חברה משלי.","l":2},{"s":"I dream about traveling around the world.","he":"אני חולם לטייל סביב העולם.","l":2}],
"Smell":[{"s":"This soup smells great.","he":"המרק הזה מריח מעולה.","l":1},{"s":"Can you smell the coffee?","he":"אתה מריח את הקפה?","l":2}],
"Spell":[{"s":"How do you spell your name?","he":"איך מאייתים את השם שלך?","l":1},{"s":"Can you spell that word for me?","he":"אתה יכול לאיית לי את המילה הזאת?","l":2}],
"Burn":[{"s":"Don't burn the onions.","he":"אל תשרוף את הבצל.","l":2},{"s":"I burned my hand on the oven.","he":"נכוויתי ביד מהתנור.","l":2}],
"Set":[{"s":"Set the alarm for six.","he":"תכוון את השעון המעורר לשש.","l":2},{"s":"We set a clear goal for this quarter.","he":"קבענו יעד ברור לרבעון הזה.","l":3}],
"Talk":[{"s":"Can we talk later?","he":"אפשר לדבר אחר כך?","l":1},{"s":"We talked about the new project.","he":"דיברנו על הפרויקט החדש.","l":1}],
"Use":[{"s":"Can I use your phone?","he":"אני יכול להשתמש בטלפון שלך?","l":1},{"s":"We use this app to track our expenses.","he":"אנחנו משתמשים באפליקציה הזאת כדי לעקוב אחרי ההוצאות שלנו.","l":2}],
"Look":[{"s":"Look at this photo.","he":"תסתכל על התמונה הזאת.","l":1},{"s":"You look tired today.","he":"אתה נראה עייף היום.","l":1}],
"Like":[{"s":"I like this song.","he":"אני אוהב את השיר הזה.","l":1},{"s":"I like pizza with a lot of cheese.","he":"אני אוהב פיצה עם הרבה גבינה.","l":1}],
"Love":[{"s":"I love my family.","he":"אני אוהב את המשפחה שלי.","l":1},{"s":"The kids love going to the beach.","he":"הילדים אוהבים ללכת לים.","l":1}],
"Hate":[{"s":"I hate waiting in line.","he":"אני שונא לחכות בתור.","l":1},{"s":"He hates cold weather.","he":"הוא שונא מזג אוויר קר.","l":2}],
